begin
  dut : entity work.alu8 port map (a => s_a, b => s_b, opcode => s_opcode, result => s_result, zero => s_zero);
  
  process
    variable l : line;
    variable got : std_logic_vector(1 to 9);
    variable errors : natural := 0;
  begin
    for i in stim'range loop
      s_a <= stim(i)(1 to 8);
      s_b <= stim(i)(9 to 16);
      s_opcode <= stim(i)(17 to 19);
      wait for 5 ns;
      got(1 to 8) := s_result;
      got(9) := s_zero;
      for b in got'range loop
        if expv(i)(b) /= '-' and got(b) /= expv(i)(b) then
          errors := errors + 1;
          if errors <= 10 then
            report "MISMATCH vector " & integer'image(i) & " bit " & integer'image(b)
              & " expected " & std_logic'image(expv(i)(b))
              & " got " & std_logic'image(got(b)) severity warning;
          end if;
        end if;
      end loop;
    end loop;
    done <= true;
    assert errors = 0
      report integer'image(errors) & " output bit(s) differ from the golden vectors"
      severity error;
    if errors = 0 then report "GOLDEN_PASS" severity note; end if;
    wait;
  end process;
end architecture;
